import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: true,
    autoplay: true,
    autoplaySpeed: 3000,
    pauseOnHover: true,
  };

  const slides = [
    { id: 1, title: "Slide 1" },
    { id: 2, title: "Slide 2" },
    { id: 3, title: "Slide 3" },
  ];

  return (
    <div
      style={{
        position: "relative",
        maxWidth: "1112px",
        
        width: "100%",
        margin: "30px auto",
        border: "15px solid #00C26D",
        borderRadius: "10px",
        backgroundColor: "#293349",
        overflow: "hidden",
      }}
    >
      {/* Kesik Çizgiler ve Noktalar */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          display: "flex",
          flexDirection: "column",
          gap: "5px",
        }}
      >
        <div
          style={{
            width: "5px",
            height: "5px",
            borderRadius: "50%",
            backgroundColor: "#fff",
          }}
        ></div>
        <div
          style={{
            width: "5px",
            height: "5px",
            borderRadius: "50%",
            backgroundColor: "#fff",
          }}
        ></div>
        <div
          style={{
            width: "5px",
            height: "5px",
            borderRadius: "50%",
            backgroundColor: "#fff",
          }}
        ></div>
      </div>
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          display: "flex",
          flexDirection: "row",
          gap: "5px",
        }}
      >
        <div
          style={{
            width: "15px",
            height: "2px",
            backgroundColor: "#fff",
            transform: "rotate(45deg)",
          }}
        ></div>
        <div
          style={{
            width: "15px",
            height: "2px",
            backgroundColor: "#fff",
            transform: "rotate(45deg)",
          }}
        ></div>
        <div
          style={{
            width: "15px",
            height: "2px",
            backgroundColor: "#fff",
            transform: "rotate(45deg)",
          }}
        ></div>
      </div>

      {/* Slider */}
      <Slider {...settings}>
        {slides.map((slide) => (
          <div
            key={slide.id}
            style={{
              height: "394px",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
              fontSize: "24px",
              fontWeight: "bold",
              backgroundColor: "#444",
            }}
          >
            {slide.title}
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default EventsSlider;
